package main

import (
 "fmt"
 "math/rand"
 "sort"
)

func main() {
 for _, seed := range []int64{43, 44} {
  p := rand.New(rand.NewSource(seed)).Perm(4)
  p = p[:2]
  sort.Ints(p)
  fmt.Println(seed, p)
 }
}

